const validators: Record<string, Validator> = {
  'user_message': validateUserMessage,
  'ping': validatePingMessage,
  'list_sessions': validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  if (!validator) {
    return {valid: false, error: `Unknown message type: ${message.type}`};
  }

  return validator(message);
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: ListSessionsMessage = {type: 'list_sessions'};

  const {limit} = message;
  if (limit !== undefined && isInvalidLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be an integer between 1 and 200'};
  }
  if (limit !== undefined) {
    result.limit = limit as number;
  }

  if (message.before === undefined) {
    return {valid: true, data: result};
  }

  const {before} = message;
  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const b = before as Record<string, unknown>;
  if (typeof b.sessionId !== 'string' || b.sessionId.length < 1 || b.sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be a string (1-128 chars)'};
  }

  if (typeof b.updatedAt !== 'string' && typeof b.updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
  }

  if (typeof b.updatedAt === 'number' && !Number.isFinite(b.updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a finite number'};
  }

  if (typeof b.updatedAt === 'string' && Number.isNaN(Date.parse(b.updatedAt))) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date string'};
  }

  result.before = {
    sessionId: b.sessionId,
    updatedAt: b.updatedAt as string | number,
  };

  return {valid: true, data: result};
}

function isInvalidLimit(limit: unknown): boolean {
  return typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 200;
}

