import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {answeringOrchestrator, askAfterConnect, stopEngines} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../types/sessionStore.js';

describe('conversation list history opt-in', () => {
  afterEach(async () => {
    await stopEngines();
  });

  async function startAndAsk(options: {history: boolean; store: SessionStore}) {
    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: async () => ({id: 'u1'}),
      sessionStore: options.store,
      orchestrator: answeringOrchestrator,
      history: {enabled: options.history},
    });
    await hal.start(0);
    const {port} = hal.server.address() as AddressInfo;
    const url = `ws://127.0.0.1:${port}/hal/ws`;

    return askAfterConnect(url, {type: 'list_sessions'});
  }

  it('answers UNSUPPORTED when history is disabled', async () => {
    const {frames} = await startAndAsk({
      history: false,
      store: new InMemorySessionStore(),
    });

    expect(frames).toContainEqual(
      expect.objectContaining({
        type: 'error',
        code: 'UNSUPPORTED',
      })
    );
  });

  it('answers UNSUPPORTED when sessionStore does not support listing', async () => {
    const {frames} = await startAndAsk({
      history: true,
      store: {
        create: id => Promise.resolve({sessionId: id, userId: 'u1', entries: []}),
        get: () => Promise.resolve(undefined),
        delete: () => Promise.resolve(true),
        count: () => Promise.resolve(0),
        clear: () => Promise.resolve(),
      } as SessionStore,
    });

    expect(frames).toContainEqual(
      expect.objectContaining({
        type: 'error',
        code: 'UNSUPPORTED',
      })
    );
  });
});

